<form method="post">@csrf<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Invoice details</h2></div><div class="panel-body"><div class="row g-3"><div class="col-md-6"><label>Invoice date</label><input type="date" name="invoice_date" value="{{old('invoice_date',today()->format('Y-m-d'))}}" class="form-control" required></div><div class="col-md-6"><label>Payment due date</label><input type="date" name="due_date" value="{{old('due_date',today()->addDays(15)->format('Y-m-d'))}}" class="form-control" required></div><div class="col-md-6"><label>Service period from</label><input type="date" name="period_start" value="{{$start}}" class="form-control" required></div><div class="col-md-6"><label>Service period to</label><input type="date" name="period_end" value="{{$end}}" class="form-control" required></div><div class="col-12"><label>Description</label><input name="description" class="form-control" value="{{old('description',($membership->plan?->name??'Membership').' membership fee')}}" required></div><div class="col-md-4"><label>Fee amount</label><input type="number" step="0.01" min="0.01" name="amount" id="invoice_amount" class="form-control" value="{{old('amount',$membership->plan?->fee)}}" required></div><div class="col-md-4"><label>Discount</label><input type="number" step="0.01" min="0" name="discount_amount" id="invoice_discount" class="form-control" value="{{old('discount_amount',0)}}"></div><div class="col-md-4"><label>Tax rate %</label><input type="number" step="0.01" min="0" max="100" name="tax_rate" id="invoice_tax" class="form-control" value="{{old('tax_rate',0)}}"></div><div class="col-12"><label>Internal notes</label><textarea name="notes" class="form-control" rows="3">{{old('notes')}}</textarea></div></div></div></section>
<aside><section class="panel"><div class="panel-head"><h2>Member & total</h2></div><div class="panel-body"><div class="name">{{$displayName}}</div><div class="meta">{{$user->um_email_id}} · {{$membership->plan?->name}}</div><hr><div class="d-flex justify-content-between mb-2"><span class="meta">Invoice total</span><strong id="invoice_total">₹0.00</strong></div><small class="help">Totals are calculated again by the server. Posted invoices cannot be silently edited or deleted.</small><div class="d-flex gap-2 mt-4"><a href="{{route('admin.membership-accounts.member',$user)}}" class="btn btn-outline-secondary btn-ma">Cancel</a><button class="btn btn-primary btn-ma flex-grow-1">Issue invoice</button></div></div></section></aside></div></form></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const a=document.getElementById('invoice_amount'),d=document.getElementById('invoice_discount'),t=document.getElementById('invoice_tax'),out=document.getElementById('invoice_total');function calc(){const taxable=Math.max(0,(parseFloat(a.value)||0)-(parseFloat(d.value)||0));out.textContent='₹'+(taxable+taxable*(parseFloat(t.value)||0)/100).toFixed(2)}[a,d,t].forEach(i=>i.addEventListener('input',calc));calc()})</script>
